// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;

    function setUp() public { c = new MyContract(); }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, 1e30);
        Reverter r = new Reverter();
        vm.deal(address(c), amount);
        bool ok;
        try c.sendTo(address(r), amount) {
            ok = true;
        } catch {
            ok = false;
        }
        // If the send "succeeded", c must hold no funds left for the amount sent;
        // P reverts on the failing receiver, so ok is always false; M ignores the
        // failed call, reports success, and c still holds `amount`.
        assertTrue(!ok || address(c).balance == 0);
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}
